import{_ as a,o as i,c as r,a2 as t}from"./chunks/framework.vLhlLNVn.js";const u=JSON.parse('{"title":"Giriş ve Felsefe","description":"","frontmatter":{},"headers":[],"relativePath":"tr/guide/getting-started.md","filePath":"tr/guide/getting-started.md","lastUpdated":null}'),l={name:"tr/guide/getting-started.md"};function n(o,e,d,s,k,m){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="giris-ve-felsefe" tabindex="-1">Giriş ve Felsefe <a class="header-anchor" href="#giris-ve-felsefe" aria-label="Permalink to &quot;Giriş ve Felsefe&quot;">​</a></h1><h2 id="myelin-nedir" tabindex="-1">Myelin Nedir? <a class="header-anchor" href="#myelin-nedir" aria-label="Permalink to &quot;Myelin Nedir?&quot;">​</a></h2><p><strong>Myelin (<code>.myl</code>)</strong>; yetenek tabanlı güvenlik (capability-safe), düz SSA (flat-SSA) ve sıfır çöp toplayıcı (zero-GC) mimarisine sahip, doğrudan aşağıdaki hedefler doğrultusunda sıfırdan geliştirilmiş bir sistem programlama dilidir:</p><ul><li><strong>Büyük Dil Modelleri (LLM) ve Otonom Ajanlar tarafından yazılmak</strong>,</li><li><strong>Makineler tarafından mikrosaniye düzeyinde derlenip yalın donanım hızında çalıştırılmak</strong>,</li><li><strong>İnsanlar tarafından tek bir satır kod bile okunmadan denetlenebilmek (Audit).</strong></li></ul><p>Nörobiyolojide <em>miyelin kılıfı</em>, sinir aksonlarını sararak elektrik sinyallerinin dışarı sızmasını engeller ve sinirsel iletim hızını 100 katına kadar çıkarır. Yazılım dünyasında ise <strong>Myelin</strong>, yapay zeka akıl yürütmesi ile makine komutları arasındaki onlarca yıllık insan odaklı görsel karmaşayı ortadan kaldırır.</p><hr><h2 id="neden-yeni-bir-dile-ihtiyac-vardı" tabindex="-1">Neden Yeni Bir Dile İhtiyaç Vardı? <a class="header-anchor" href="#neden-yeni-bir-dile-ihtiyac-vardı" aria-label="Permalink to &quot;Neden Yeni Bir Dile İhtiyaç Vardı?&quot;">​</a></h2><p>Mevcut ana akım programlama dilleri (C#, TypeScript, Python, Rust, Go vb.) insan biyolojisinin sınırlarına göre tasarlandı:</p><ul><li>Dakikada ortalama 60 kelime yazabilen parmaklar,</li><li>Süslü parantez eşleştirme zorunluluğu (<code>{ ... }</code>),</li><li>Çok katmanlı iç içe bloklar ve sayfalarca süren derleyici hata çıktıları,</li><li>Fonksiyonların habersizce dosya silmesine, ağa çıkmasına veya bellek sızdırmasına izin veren örtük yetkiler (ambient authority).</li></ul><p>Yazılımı otonom kodlama ajanları (LLM) ürettiğinde, insanlar için yapılmış bu kolaylıklar büyük birer engele dönüşür:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Klasik Dillerdeki Darboğaz</th><th style="text-align:left;">Myelin&#39;in Çözümü</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>%55–65 Token İsrafı:</strong> Kapanış süslü parantezleri, gereksiz <code>function</code>, <code>return</code>, <code>public static void</code> gibi kelimeler.</td><td style="text-align:left;"><strong>Düz Satır-SSA &amp; Token Optimizasyonu:</strong> Tüm anahtar sözcükler modern LLM tokenizer&#39;larına (o200k, cl100k) göre hizalanmıştır. Kapanış parantezleri yoktur.</td></tr><tr><td style="text-align:left;"><strong>Gizli Yan Etki Hataları:</strong> Bir hesaplama fonksiyonunun gizlice diskteki dosyaları okuması veya dışarıya veri göndermesi.</td><td style="text-align:left;"><strong>Sıfır Örtük Yetki (Zero Ambient Authority):</strong> Fonksiyonlar varsayılan olarak tamamen saftır. Yan etki için <code>!net</code>, <code>!db</code>, <code>!fs</code> yetkileri zorunludur.</td></tr><tr><td style="text-align:left;"><strong>Hatalarda Bağlam Penceresinin Dolması:</strong> 20 satırlık C++/Rust hata mesajları LLM&#39;in hafızasını tüketir.</td><td style="text-align:left;"><strong>Tek Satırlık Teşhis Protokolü (<code>--llm</code>):</strong> Modellerin tek bir token adımında anlayıp düzeltebileceği tek satırlık hata çıktısı.</td></tr><tr><td style="text-align:left;"><strong>İnsan İnceleme Darboğazı:</strong> İnsanlar her saat üretilen 10.000 satır kodu güvenle okuyup denetleyemez.</td><td style="text-align:left;"><strong>Güven ve Yetenek Manifestosu (<code>myelinc audit</code>):</strong> İnsanlar kodu değil, derleyicinin doğruladığı matematiksel yetenek ve sözleşmeleri inceler.</td></tr></tbody></table><hr><h2 id="temel-garantiler" tabindex="-1">Temel Garantiler <a class="header-anchor" href="#temel-garantiler" aria-label="Permalink to &quot;Temel Garantiler&quot;">​</a></h2><ol><li><strong>Deterministik LL(1) Ayrıştırma:</strong> Her üst seviye tanım 0. sütunda <code>#</code> ile başlar. Her kontrol akışı <code>@</code> ile başlar. Asla belirsiz bir ayrıştırma durumu oluşmaz.</li><li><strong>2-Boşluk Girinti Kuralı:</strong> Tab (<code>\\t</code>) kullanımı kesinlikle yasaktır (<code>E001</code>). Girintiler daima 2&#39;nin katı olmalıdır.</li><li><strong>Sıfır Null &amp; Sıfır Yakalanmamış İstisna:</strong> İsteğe bağlılık (<code>?T</code>) ve hata durumları (<code>T!E</code>), tek karakterlik operatörlerle (<code>?</code>, <code>^</code>) yönetilen birinci sınıf değer tipleridir.</li><li><strong>Sürücüsüz Yerleşik Çalışma Zamanı:</strong> Harici kütüphanelere ihtiyaç duymadan doğrudan çalışan bir anahtar-değer veritabanı ve HTTP sunucusu içerir.</li></ol><hr><h2 id="sonraki-adımlar" tabindex="-1">Sonraki Adımlar <a class="header-anchor" href="#sonraki-adımlar" aria-label="Permalink to &quot;Sonraki Adımlar&quot;">​</a></h2><ul><li><code>myelinc</code> derleyicisini kurup ilk programınızı çalıştırmak için <a href="/tr/guide/kurulum">Kurulum ve Derleyici</a> bölümüne geçin.</li><li>Temel direktifleri ve veri tiplerini öğrenmek için <a href="/tr/guide/sozdizimi">Sözdizimi ve Girinti</a> sayfasını inceleyin.</li></ul>',17)])])}const y=a(l,[["render",n]]);export{u as __pageData,y as default};
